const feathers = require('@feathersjs/feathers');
const express = require('@feathersjs/express');
const { authenticate } = require('@feathersjs/authentication').hooks;
const { Forbidden, NotFound } = require('@feathersjs/errors');
const memory = require('feathers-memory');

const app = express(feathers());
app.use(express.json());
app.configure(express.rest());

app.use('/legal-contracts', memory({ id: 'id', startId: 1 }));

const contractsService = app.service('legal-contracts');

contractsService.hooks({
  before: {
    patch: [
      authenticate('jwt'),
      async (context) => {
        // Enforce object-level company ownership on target contract
        const existing = await context.service.get(context.id, {
          ...context.params,
          provider: undefined
        });

        if (!existing) {
          throw new NotFound('Contract not found');
        }

        if (existing.companyId !== context.params.user.companyId) {
          throw new Forbidden('Access denied: cannot modify contracts belonging to another company');
        }

        context.data.updatedAt = new Date();
        return context;
      }
    ]
  }
});
